import { useEffect, useId, useRef } from 'react';
import type { MouseEvent, ReactNode } from 'react';
import { cx } from '@/lib/cx';
import './drawer.css';

/**
 * B21 · Drawer — the slide-over. A paper panel entering from the screen
 * edge for detail-in-context work: inspect a row, edit a record, review
 * before commit — WITHOUT losing the sheet behind it. Built on native
 * <dialog>.showModal(): focus trap, Esc, ::backdrop, top layer for free.
 * Anything that replaces the whole task is a full-screen Dialog instead.
 */
export interface DrawerProps {
  open: boolean;
  onClose: () => void;
  title: string;
  /** Mono context line under the title, e.g. "ORD-2291 · 24 JUL". */
  context?: string;
  side?: 'right' | 'left';
  /** sm 360 · md 480 (default) · lg 640 · full — a mobile-style takeover. */
  size?: 'sm' | 'md' | 'lg' | 'full';
  /** Footer actions, right-aligned: ghost cancel + ONE primary/danger. */
  footer?: ReactNode;
  /** Scrim click closes by default; disable for unsaved-work drawers. */
  dismissible?: boolean;
  children: ReactNode;
}

export function Drawer({
  open,
  onClose,
  title,
  context,
  side = 'right',
  size = 'md',
  footer,
  dismissible = true,
  children,
}: DrawerProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const titleId = useId();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) el.showModal();
    if (!open && el.open) el.close();
  }, [open]);

  function handleClick(e: MouseEvent<HTMLDialogElement>) {
    if (!dismissible) return;
    if (e.target === ref.current) onClose();
  }

  return (
    <dialog
      ref={ref}
      className={cx('sv-drawer', `sv-drawer--${side}`, `sv-drawer--${size}`)}
      aria-labelledby={titleId}
      onCancel={(e) => {
        e.preventDefault();
        onClose();
      }}
      onClick={handleClick}
      onClose={() => open && onClose()}
    >
      <div className="sv-drawer__panel">
        <header className="sv-drawer__head">
          <div className="sv-drawer__titles">
            <h2 className="sv-drawer__title" id={titleId}>
              {title}
            </h2>
            {context && <p className="sv-drawer__context sv-mono">{context}</p>}
          </div>
          <button
            type="button"
            className="sv-drawer__close"
            aria-label={`Close ${title}`}
            onClick={onClose}
          >
            <svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true">
              <path
                d="M2 2l8 8M10 2l-8 8"
                stroke="currentColor"
                strokeWidth="1.6"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </header>
        <div className="sv-drawer__body">{children}</div>
        {footer && <footer className="sv-drawer__footer">{footer}</footer>}
      </div>
    </dialog>
  );
}

/* B21 · Drawer — slide-over on native <dialog>. Transform/opacity only;
   both collapse to 0ms under prefers-reduced-motion via the tokens. */

@layer sv-components {
  .sv-drawer {
    position: fixed;
    inset: 0 0 0 auto;
    height: 100dvh;
    max-height: 100dvh;
    width: min(480px, 100vw);
    max-width: 100vw;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: var(--sv-paper);
    color: var(--sv-ink);
    box-shadow: var(--sv-shadow);
  }

  .sv-drawer--left {
    inset: 0 auto 0 0;
  }

  .sv-drawer--sm {
    width: min(360px, 100vw);
  }

  .sv-drawer--lg {
    width: min(640px, 100vw);
  }

  .sv-drawer--full {
    width: 100vw;
  }

  .sv-drawer::backdrop {
    background: var(--sv-scrim);
  }

  /* Entry: slide from the owning edge. Exit is instant (dialog closes);
     honest and cheaper than choreographing a close animation. */
  .sv-drawer[open] {
    transform: translateX(0);
    transition: transform var(--sv-t) ease-out;
  }

  @starting-style {
    .sv-drawer--right[open] {
      transform: translateX(24px);
    }

    .sv-drawer--left[open] {
      transform: translateX(-24px);
    }
  }

  .sv-drawer__panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
  }

  .sv-drawer__head {
    display: flex;
    align-items: flex-start;
    gap: var(--sv-s3);
    padding: var(--sv-s5) var(--sv-s6) var(--sv-s4);
    border-bottom: 1px solid var(--sv-line);
  }

  .sv-drawer__titles {
    flex: 1;
    min-width: 0;
  }

  .sv-drawer__title {
    font-size: 15px;
    font-weight: 700;
    text-wrap: balance;
  }

  .sv-drawer__context {
    margin-top: var(--sv-s1);
    font-size: 10.5px;
    color: var(--sv-ink-soft);
  }

  .sv-drawer__close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    flex: none;
    border: 0;
    border-radius: var(--sv-r);
    background: none;
    color: var(--sv-ink-soft);
    cursor: pointer;
    transition: background-color var(--sv-t-fast), color var(--sv-t-fast);
  }

  .sv-drawer__close:hover {
    background: var(--sv-wall);
    color: var(--sv-ink);
  }

  .sv-drawer__close:focus-visible {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  .sv-drawer__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: var(--sv-s5) var(--sv-s6);
    font-size: 13px;
    line-height: 1.55;
  }

  .sv-drawer__footer {
    display: flex;
    justify-content: flex-end;
    gap: var(--sv-s2);
    padding: var(--sv-s4) var(--sv-s6);
    border-top: 1px solid var(--sv-line);
    background: var(--sv-paper);
  }
}
